### Severity: CRITICAL ⚠️

#### 0. Secrets Management - File-Based vs Secrets Manager

**Severity:** CRITICAL - Secrets exposure risk
**Risk:** Secrets loaded from .env files are at high risk of being exposed, committed to version control, or leaked

**Observation:**
- Found `.env.test` file in project root
- No `.env.example` file to document required environment variables
- No secrets manager integration (AWS Secrets Manager, HashiCorp Vault, etc.)
- Environment variables would be exposed if queried by any process

**Recommendation:**
```javascript
// SECURITY BEST PRACTICES FOR SECRETS

// 1. DO NOT commit .env files to version control
# .gitignore
.env
.env.local
.env.*.local
!env.example

# 2. Create environment template file
// .env.example
PORT=3000
NODE_ENV=development
DATABASE_URL=your_database_url_here
JWT_SECRET=your_jwt_secret_here
SESSION_SECRET=your_session_secret_here
API_KEY=your_api_key_here

# 3. Use .env files only in specific contexts (dev, test, staging)
// .env.development (never commit this)
NODE_ENV=development
DATABASE_URL=postgres://dev_user:dev_password@localhost/mydb

// .env.test (never commit this)
NODE_ENV=test
DATABASE_URL=postgres://test_user:test_password@localhost/testdb

// .env.production (never commit this - set on server)
NODE_ENV=production
DATABASE_URL=postgres://prod_user:prod_password@prod-db/mydb
API_KEY=encrypted_api_key_key
JWT_SECRET=encrypted_jwt_secret
# All secrets should be encrypted at rest

// 4. Validate environment variables at startup
require('dotenv').config();

const requiredEnvVars = ['DATABASE_URL', 'JWT_SECRET', 'SESSION_SECRET', 'API_KEY'];
const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingEnvVars.length > 0) {
  console.error('❌ ERROR: Missing required environment variables:');
  missingEnvVars.forEach(varName => console.error(`  - ${varName}`));
  process.exit(1);
}

// 5. Use secrets manager for production (AWS example)
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function getSecret(secretName) {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);
  return JSON.parse(response.SecretString);
}

// Example usage
const secretData = await getSecret('production/database-credentials');
const databaseUrl = secretData.database_url;
const dbPassword = secretData.password;

// 6. HashiCorp Vault example (alternative)
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN,
});

async function getSecretFromVault(secretsPath) {
  const result = await vault.read({ path: secretsPath });
  return result.data.data;
}

// 7. Rotate secrets regularly
// Setup automated secret rotation policies in AWS Secrets Manager

# 8. Use encryption for sensitive files
npm install dotenv-encryption-service

// Encrypt secrets before committing
const encrypter = require('dotenv-encryption-service');
const encrypted = encrypter.encrypt('my-secret-key');

// Decrypt in production
const decrypted = encrypter.decrypt(process.env.ENCRYPTED_SECRET);

// 9. NEVER verify .env files into git
echo ".env" >> .gitignore
echo ".env.*.local" >> .gitignore

# 10. Security checklist for .env files
[ ] No .env files checked into GitHub/GitLab/Bitbucket
