const sanitizeHtml = require('sanitize-html');

// Sanitize input middleware
const sanitizeInput = (req, res, next) => {
    const sanitize = (text) => {
        return sanitizeHtml(text || '', {
            allowedTags: [],
            allowedAttributes: {},
            disallowedTagsMode: 'discard',
            allowedSchemes: ['https', 'mailto'],
        });
    };

    if (req.body) {
        if (req.body.name) req.body.name = sanitize(req.body.name);
        if (req.body.email) req.body.email = sanitize(req.body.email);
        if (req.body.comment) req.body.comment = sanitize(req.body.comment);
    }

    if (req.query) {
        if (req.query.search) req.query.search = sanitize(req.query.search);
    }

    if (req.params) {
        Object.keys(req.params).forEach(param => {
            if (typeof req.params[param] === 'string') {
                req.params[param] = sanitize(req.params[param]);
            }
        });
    }

    if (req.cookies) {
        Object.keys(req.cookies).forEach(cookie => {
            if (typeof req.cookies[cookie] === 'string') {
                req.cookies[cookie] = sanitize(req.cookies[cookie]);
            }
        });
    }

    next();
};

// Apply to protected routes
app.use('/api/user', sanitizeInput);
