```javascript
const { body, param, validationResult, sanitizeBody, sanitizeQuery } = require('express-validator');

// Route with comprehensive validation
app.get('/users/:id', [
  param('id').isInt({ min: 1 }).withMessage('Valid user ID required'),
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Sanitize and validate before DB query
  const userId = parseInt(sanitizeQuery(req.params.id));

  const result = await db.query(
    'SELECT id, name, email FROM users WHERE id = $1 AND deleted_at IS NULL',
    [userId]
  );

  if (result.rows.length === 0) {
    return res.status(404).json({ message: 'User not found' });
  }

  res.json(result.rows[0]);
});

// POST endpoint with validation
app.post('/users', [
  body('name').trim().isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters'),
  body('email').isEmail().normalizeEmail().withMessage('Valid email required'),
  body('password').isLength({ min: 8 }).matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .withMessage('Password must contain uppercase, lowercase, and number'),
  body('age').optional().isInt({ min: 18, max: 120 }).withMessage('Valid age required'),
  sanitizeBody('name').escape(),
  sanitizeBody('email').normalizeEmail(),
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(422).json({ errors: errors.array() });
  }

  const { name, email, password, age } = req.body;

  // Check for existing user
  const existing = await db.query(
    'SELECT id FROM users WHERE email = $1 OR email = $2',
    [email, sanitizeBody(email)]
  );

  if (existing.rows.length > 0) {
    return res.status(400).json({ message: 'Email already registered' });
  }

  // Hash password with bcrypt
  const salt = await bcrypt.genSalt(10);
  const hashedPassword = await bcrypt.hash(password, salt);

  // Insert user with validated data
  const result = await db.query(
    `INSERT INTO users (name, email, password_hash, age)
     VALUES ($1, $2, $3, $4)
     RETURNING id, name, email, created_at`,
    [sanitizeBody(name), email, hashedPassword, age || null]
  );

  res.status(201).json({ user: result.rows[0] });
});
