    if (missing.length > 0) {
      console.error('Missing environment variables:', missing.join(', '));
      process.exit(1);
    }
  }

  // Mask secrets in console output
  logSecretAccess(secrets = []) {
    const env = Object.keys(process.env);
    const secretRegex = /^[A-Z0-9_]+_SECRET|KEY|TOKEN|PASSWORD|DATABASE_URL/i;

    const [masked,.logged] = env.reduce(([masked, logged], key) => {
      if (secrets.includes(key) || secretRegex.test(key)) {
        return [masked, [...logged, `${key}=${'*'.repeat(10)}`]];
      }
      return [masked, logged];
    }, [[], []]);

