```javascript
const { VaultClient } = require('node-vault');
const AWS = require('aws-sdk');

class SecretsHybridManager {
  constructor() {
    this.vault = new VaultClient({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN,
    });

    this.secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION,
    });

    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
    this.loadTimestamp = Date.now();
  }

  async getSecret(key) {
    // Cache check
    const cacheEntry = this.cache.get(key);
    if (cacheEntry && (Date.now() - cacheEntry.timestamp < this.cacheTTL)) {
      return cacheEntry.value;
    }

    // Try Vault first (if available)
    if (process.env.VAULT_ADDR) {
      const vaultSecret = await this.vault.secrets.readSecret({
        path: `secret/data/${key}`,
      });

      if (vaultSecret) {
        return this._cacheAndReturn(key, vaultSecret);
      }
    }

    // Fallback to AWS Secrets Manager
    const awsSecret = await this.secretsManager.getSecretValue({
      SecretId: key,
    }).promise();

    return this._cacheAndReturn(key, JSON.parse(awsSecret.SecretString));
  }

  _cacheAndReturn(key, value) {
    const entry = {
      value,
      timestamp: Date.now()
    };
    this.cache.set(key, entry);
    return value;
  }

  // Bulk fetch for startup
  async loadAll(requiredSecrets) {
    const missing = [];

    const promises = requiredSecrets.map(async (key) => {
      try {
        const value = await this.getSecret(key);
        process.env[key] = value;
      } catch (error) {
        console.error(`Failed to load secret ${key}:`, error);
        missing.push(key);
      }
    });

    await Promise.all(promises);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    return true;
  }
}

// Application bootstrap
(async () => {
  const secretsManager = new SecretsHybridManager();

  await secretsManager.loadAll([
    'DATABASE_URL',
    'STRIPE_SECRET_KEY',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'JWT_SECRET',
    'JWT_EXPIRES_IN',
  ]);

  // Now start application
  const app = require('./app');
  app.listen(process.env.PORT, () => {
    console.log(`✅ Application started on port ${process.env.PORT}`);
  });
})();
