    .email({
      minDomainSegments: 2,
      tlds: { allow: ['com', 'org', 'net', 'io', 'co'] }
    })
    .toLowerCase()
    .trim(),

  // Password validation
  password: Joi.string()
    .pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/)
    .messages({
      'string.pattern.base': 'Password must be 8+ chars with uppercase, lowercase, number, and special char'
    }),

  // Date validation
  birthDate: Joi.date()
    .max('now')
    .iso(),

  // URL validation
  website: Joi.string()
    .uri()
    .max(500)
});

// Validation middleware
const validateRequest = (schema, property = 'body') => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req[property], {
      abortEarly: false,
      stripUnknown: true,
      convert: true
    });

    if (error) {
      return res.status(400).json({
        error: 'Validation failed',
        details: error.details.map(detail => ({
          field: detail.path.join('.'),
          message: detail.message,
          type: detail.type
        }))
      });
    }

    // Attach validated data to request
    req[property] = value;
    next();
  };
};

// Apply to routes
app.post('/users', validateRequest(userSchema), (req, res) => {
  const userData = req.body; // This is already validated
  res.status(201).json(userData);
});

app.put('/users/:id', validateRequest(userSchema), (req, res) => {
  res.json(req.body);
});
