// Validate URLs before making requests
function isValidUrl(url, callback) {
  // Remove protocol for validation
  const urlObj = new URL(url);
  const protocol = urlObj.protocol.toLowerCase();
  const hostname = urlObj.hostname.toLowerCase();

  // Only allow http/https (not other protocols)
  if (!['http:', 'https:'].includes(protocol)) {
    return callback(false);
  }

  // Check against allowed hosts
  // Must be subdomain of allowed hosts
  const isValid = allowedHosts.some(host => {
    const allowed = host.toLowerCase();
    const normalizedHost = hostname.endsWith(`.${allowed}`) || hostname === allowed;
    // Prevents: https://evil.com/malicious
    return normalizedHost && hostname.length > allowed.length;
  });

  callback(isValid);
  return isValid;
}

