const Redis = require('ioredis');
const { RateLimiterRedis, RateLimiterMemory } = require('rate-limiter-flexible');

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

// Options for different rate limiting strategies
const options = {
  storeClient: redis,
  points: 100, // 100 requests
  duration: 60, // per 60 seconds by default
  keyPrefix: 'api'
};

// IP-based rate limiter
const ipLimiter = new RateLimiterRedis(options);

// User-based rate limiter
const userLimiter = new RateLimiterRedis({
  ...options,
  keyPrefix: 'api:user',
  keyGenerator: (req) => req.user?.id || 'anonymous'
});

// Apply different limits
app.get('/health', ipLimiter); // 100 per minute
app.get('/users', userLimiter); // 50 per minute per user
app.post('/api', ipLimiter); // 100 per minute for all IPs

// Custom rate limit endpoint
app.get('/rate-limit-info', (req, res, next) => {
  if (req.user?.id) {
    userLimiter.get(req.user.id)
      .then((consumedPoints) => {
        const remainingPoints = options.points - consumedPoints;
        const retryAfter = Math.ceil((options.duration * 1000) / (options.points - consumedPoints));

        res.json({
          limit: options.points,
          remaining: remainingPoints,
          consumedPoints,
          retryAfter
        });
      })
      .catch(next);
  } else {
    ipLimiter.get(req.ip)
      .then((consumedPoints) => {
        const remainingPoints = options.points - consumedPoints;
        const retryAfter = Math.ceil((options.duration * 1000) / (options.points - consumedPoints));

        res.json({
