# Security Review of app.js

## Executive Summary

This document provides a comprehensive security review of app.js.

**Overall Risk Level:** MEDIUM-HIGH
**Critical Issues Found:** 0
**High Severity Issues:** 2
**Medium Severity Issues:** 3
**Low Severity Issues:** 1

---

## Critical Vulnerabilities (Not Found)

✓ No SQL injection vulnerabilities (no database interactions)
✓ No NoSQL injection vulnerabilities (no NoSQL databases)
✓ No proper insecure deserialization issues (no deserialization)
✓ No security misconfigurations at configuration level
✓ No improper logging issues that could leak sensitive data

---

## High Severity Issues

### H1: **Missing Rate Limiting** ⚠️ HIGH

**Risk:** Attackers can overwhelming the application with requests, causing Denial of Service.

**Location:** Global application

**Description:**
The application uses no rate limiting protection, making it vulnerable to DoS attacks through:
- Brute force attacks on vulnerable endpoints
- Resource exhaustion through request flooding
- Cloud billing exhaustion attacks

**Code Location:**
```javascript
// Before server started - no middleware protection
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Recommended Fix:** Rate limiting middleware

```javascript
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

// Apply security headers first
app.use(helmet());

// Create rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,
});

// Apply to all routes
app.use(limiter);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Why Rate Limiting is Essential:**
- Prevents DoS/DDoS attacks at the application boundary
- Protects against brute force attacks
- Defends against malicious scraping
- Reduces server resource consumption

---

### H2: **Missing Content Security Policy (CSP)** ⚠️ HIGH

**Risk:** Cross-Site Scripting (XSS) attacks can potentially bypass WAFs if CSP is not implemented consistently.

**Location:** Server configuration

**Description:**
No Content Security Policy header is set, leaving the application vulnerable to XSS attacks, inline script execution, and data injection.

**Code Location:**
```javascript
const express = require('express');
const app = express();

// Missing security headers here
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommended Fix:** Implement comprehensive security headers

```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// Helmet provides comprehensive security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
      baseUri: ["'self'"],
      formAction: ["'self'"],
      frameAncestors: ["'none'"],
    },
  },
  dnsPrefetchControl: false, // If you know you need blocked domains
  expectCt: {
    maxAge: 86400,
    enforce: false,
  },
  forcedHttpsHeader: null, // Use only if behind actual HTTPS proxy
  originAgentCluster: null,
  referrerPolicy: { policy: 'no-referrer' },
  xssFilter: true,
}));

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Alternative: More permissive CSP (if needed for external resources)**

```javascript
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'", "https://cdn.example.com"],
      imgSrc: ["'self'", "data:", "https://cdn.example.com"],
      connectSrc: ["'self'", "https://api.example.com"],
      // ... other directives
    },
  },
}));
```

---

## Medium Severity Issues

### M1: **Missing HTTPS Enforcement** ⚠️ MEDIUM

**Risk:** Man-in-the-middle attacks and data confidentiality violations.

**Location:** Server configuration

**Description:**
Server listens on HTTP port 3000 without enforcing HTTPS. All communication including cookies is transmitted in cleartext.

**Code Location:**
```javascript
app.listen(3000, () => {  // Should use HTTPS
  console.log('Server running on port 3000');
});
```

**Recommended Fix:** HTTPS with certificate management

```javascript
const fs = require('fs');
const https = require('https');
const app = express();

// For development with self-signed certificates
const httpsOptions = {
  key: fs.readFileSync('certs/localhost-key.pem'),
  cert: fs.readFileSync('certs/localhost.pem'),
  // For production with paid certificates
  // key: fs.readFileSync('/etc/ssl/private/server-key.pem'),
  // cert: fs.readFileSync('/etc/ssl/certs/server-cert.pem'),
};

// OR use Let's Encrypt with certbot
// See: https://letsencrypt.org/docs/

// Or use a reverse proxy (recommended for production)
// Nginx/Apache will handle HTTPS termination

https.createServer(httpsOptions, app).listen(3000, () => {
  console.log('HTTPS server running on port 3000');
});

module.exports = app;
```

**Production Deployment Example (with reverse proxy):**

```javascript
// app.js - configure for reverse proxy
const express = require('express');
const app = express();

// Trust the proxy header for proper IP detection
app.set('trust proxy', 1);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

module.exports = app;
```

**Nginx configuration (proxy):**
```nginx
server {
    listen 443 ssl http2;
    server_name yourdomain.com;

    ssl_certificate /etc/letsencrypt/live/yourdomain.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/yourdomain.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    location / {
        proxy_pass http://localhost:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_cache_bypass $http_upgrade;
    }
}
```

---

### M2: **Missing Input Validation and Sanitization** ⚠️ MEDIUM

**Risk:** Various injection attacks and malformed input handling.

**Location:** All endpoints

**Description:**
While this is a simple API with limited user input, there are no explicit input validation measures. In production scenarios, information from headers or parameters would need validation.

**Code Location:**
```javascript
app.get('/users', (req, res) => {
  // No validation of request parameters or headers
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommended Fix:** Implement input validation and sanitization

```javascript
const express = require('express');
const { body, query, param, validationResult } = require('express-validator');
const sanitizeHtml = require('sanitize-html');

const app = express();

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      errors: errors.array().map(err => err.msg),
    });
  }
  next();
};

// Route configuration with validation
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users',
  [
    // Validate query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
  ],
  validateRequest,
  (req, res) => {
    const { limit = 100, offset = 0 } = req.query;

    // Validate sanitized input
    const validatedLimit = Math.min(Math.max(1, parseInt(limit)), 100);
    const validatedOffset = Math.max(0, parseInt(offset));

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]).limit(validatedLimit).skip(validatedOffset);
  }
);

app.use((req, res, next) => {
  next(new Error('Not Found'));
});

// Error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({
    status: 'error',
    message: 'Internal server error',
  });
});

module.exports = app;
```

**Complete Validation Rules Example:**
```javascript
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty()
      .isLength({ min: 2, max: 50 })
      .matches(/^[a-zA-Z\s\-']+$/)
      .withMessage('Name must be 2-50 characters with letters, spaces, hyphens, and apostrophes only'),
    body('email')
      .trim()
      .notEmpty()
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email is required'),
    body('age')
      .optional()
      .isInt({ min: 13, max: 120 })
      .withMessage('Age must be between 13 and 120'),
  ],
  validateRequest,
  (req, res) => {
    // Access sanitized data
    const { name, email, age } = req.body;

    // Security: Sanitize before database storage
    const sanitized = {
      name: sanitizeHtml(name, {
        allowedTags: [],
        allowedAttributes: {},
      }),
      email: sanitizeHtml(email, {
        allowedTags: [],
        allowedAttributes: {},
      }),
      age: age !== undefined ? parseInt(age) : null,
    };

    // Process user...
    res.json({ status: 'created', userId: 3 });
  }
);
```

---

### M3: **CORS Configuration Missing (Not applicable for this API, but important)** ⚠️ MEDIUM

**Note:** For this specific API with all CORS origins allowed, no strict CORS configuration is needed. However, if this endpoint changes to allow client-side rendering (SPA), CORS becomes critical.

**Description:** No CORS middleware configured. For an API with no client-side consumption, this is not an immediate concern.

**When CORS becomes required:**
```javascript
const cors = require('cors');

// Strict CORS - allow only specific origins
app.use(cors({
  origin: ['https://trusted-domain.com', 'https://another.trusted-domain.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));

// OR permissive CORS for development
app.use(cors());

// OR restricted CORS - allow all except specific domains
app.use(cors({
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps, curl, etc.)
    if (!origin) return callback(null, true);

    if (['bad-domain.com', 'malicious-site.com'].includes(origin)) {
      return callback(new Error('Not allowed by CORS policy'));
    }

    callback(null, true);
  },
}));
```

---

### M4: **No Authorization or Authentication** ⚠️ MEDIUM

**Risk:** Anyone can access endpoints without any authentication.

**Location:** All unprotected routes

**Description:** All endpoints are publicly accessible without any form of authentication or authorization. While this matches the simple purpose of the API, it's not secure for production use.

**Code Location:**
```javascript
// All endpoints are publicly accessible
app.get('/health', (req, res) => { ... });
app.get('/users', (req, res) => { ... });
```

**Recommended Fix:** Implement authentication system

```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const rateLimit = require('express-rate-limit');

// Rate limiting for login attempts
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // limit each IP to 5 login attempts per window
  message: 'Too many login attempts, please try again later',
  skipSuccessfulRequests: true,
});

const app = express();
app.use(express.json());

// Simple in-memory user store (use database in production)
const users = new Map();

// Generate JWT secret (store in environment variable in production)
const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-in-production';

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Login endpoint
app.post('/login',
  [
    body('email')
      .isEmail()
      .withMessage('Invalid email'),
    body('password')
      .isLength({ min: 8 })
      .withMessage('Password must be at least 8 characters'),
  ],
  validateRequest,
  loginLimiter,
  async (req, res) => {
    const { email, password } = req.body;

    // Simple placeholder - use real user lookup in database
    const user = Array.from(users.values()).find(u => u.email === email);
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Validate password (with real hashing in production)
    /* const validPassword = await bcrypt.compare(password, user.password); */
    const validPassword = password === user.password; // Only for demo

    if (!validPassword) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const accessToken = jwt.sign(
      { email: user.email, id: user.id },
      JWT_SECRET,
      { expiresIn: '1h' }
    );

    res.json({ accessToken });
  }
);

// Protected endpoint example
app.get('/protected',
  authenticateToken,
  (req, res) => {
    res.json({ message: 'This is protected data', user: req.user });
  }
);

// Public endpoint - still accessible
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

function setupAuthDB() {
  // Demo setup
  const hashedPassword = 'hashedPassword'; // In production: await bcrypt.hash(password, 10);
  users.set(1, {
    id: 1,
    email: 'alice@example.com',
    name: 'Alice',
    password: hashedPassword
  });
}

// Call this when the app starts
setupAuthDB();
```

**Recommended: Environment-based configuration for sensitive data**
```javascript
