### M5: **Missing Request Logging and Monitoring** ⚠️ MEDIUM

**Risk:** Difficulty detecting attacks and security incidents.

**Code Location:** No logging middleware

**Recommended Fix:** Implement structured logging

```javascript
const morgan = require('morgan');
const axios = require('axios');

// Basic logging for local development
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
} else {
  // Production logging with sanitization
  app.use(morgan('combined', {
    skip: (req, res) => res.statusCode < 400,
  }));
}

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();
  const requestId = generateRequestId();

  // Attach ID to requests for tracing
  req.requestId = requestId;
  res.setHeader('X-Request-ID', requestId);

  // Log request
  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  console.log(`${new Date().toISOString()} [${requestId}] ${req.method} ${req.path}`);

  // Log response
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logData = {
      requestId,
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
    };

    // Redact sensitive info in logs
    if (req.body && req.body.password) {
      logData.passwordRedacted = true;
    }

    console.log(JSON.stringify(logData));

    // Send error to monitoring system
    if (res.statusCode >= 400) {
      reportToMonitoring(logData);
    }
  });

  next();
});

function generateRequestId() {
  return `req-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

function reportToMonitoring(data) {
  // Send error to monitoring service (e.g., Sentry, Datadog, New Relic)
  // Example: sentry.captureException(new Error(`HTTP error: ${data.statusCode}`));
  console.error('Security Alert:', data);
}

module.exports = app;
```

