### 2. ❌ Missing Rate Limiting (OWASP A07:2021 - Identification and Authentication Failures)

**Problem:**
- No protection against brute force attacks
- No limits on request rates
- Vulnerable to DoS/DDoS attacks
- No authentication mechanisms at all

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply to all routes (customize as needed)
app.use(generalLimiter);

// Stronger limiting for sensitive endpoints
const sensitiveLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many failed attempts, please try again later' },
  skipSuccessfulRequests: true,
});

// For authentication endpoints
// app.post('/login', sensitiveLimiter, authController.login);
```

---

### 3. ❌ No Authentication or Authorization (OWASP A07:2021, A05:2021)

**Problem:**
- No authentication mechanism
- No authorization checks
- Public data exposure
- All endpoints accessible to anyone

**Recommendation:**
```javascript
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');

// JWT Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access denied' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
}

// Role-based authorization middleware
function requireRole(role) {
  return (req, res, next) => {
    if (!req.user || req.user.role !== role) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// Apply to protected routes
app.get('/api/protected', authenticateToken, (req, res) => {
  res.json({ data: 'This is protected data' });
});

app.get('/api/admin', authenticateToken, requireRole('admin'), (req, res) => {
  res.json({ data: 'Admin only data' });
));
```

