**Recommendation:** Add security middleware to provide defense-in-depth:

```javascript
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const hpp = require('hpp');

// Apply security headers (Defense-in-Depth)
app.use(helmet());

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP'
  }
});
app.use('/users', limiter); // Apply only to /users endpoint

// Prevent HTTP Parameter Pollution attacks
app.use(hpp());

// CSP and other additional headers
helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
  },
});

// Customize X-Frame-Options and X-Content-Type-Options
app.use(helmet.noSniff());
app.use(helmet.frameguard({ action: 'sameorigin' }));

// HSTS (HTTPS only for production)
if (process.env.NODE_ENV === 'production') {
  app.use(helmet.hsts({
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }));
}
```

